awaitable<void> react(tcp::socket s) {
  for (;;) {
    auto req = co_await async_read_request(s);                    // async layer
    co_await work_channel.async_send(error_code{}, req);          // hand-off
    auto res = co_await result_channel.async_receive(use_awaitable);
    co_await async_write(s, res);
  }
}

class Worker : public ACE_Task<ACE_MT_SYNCH> {          // queueing + synchronous layer
 public:
  int svc() override {
    ACE_Message_Block *mb;
    while (getq(mb) != -1) { handle(mb); mb->release(); }
    return 0;
  }
};
